with candidates (topic, prompt, options, correct_answer, explanation) as (
  values
  -- 1. Quantities, units and dimensions (8)
  ($q$Physical Quantities and Units$q$, $q$A runner's speed is measured in metres per second. Which base quantities combine to form this unit?$q$, $q${"A":"Length and time","B":"Mass and time","C":"Current and length","D":"Temperature and mass"}$q$::jsonb, $q$A$q$, $q$Speed is distance divided by time, so its dimension is length per unit time.$q$),
  ($q$Physical Quantities and Units$q$, $q$Which listed quantity is a base SI quantity rather than a derived one?$q$, $q${"A":"Force","B":"Mass","C":"Density","D":"Pressure"}$q$::jsonb, $q$B$q$, $q$Mass is a base quantity measured in kilograms; the others combine base quantities.$q$),
  ($q$Physical Quantities and Units$q$, $q$A student writes force in kg m s⁻². Which relation supports this unit?$q$, $q${"A":"Force = mass ÷ speed","B":"Force = time × distance","C":"Force = mass × acceleration","D":"Force = pressure ÷ area"}$q$::jsonb, $q$C$q$, $q$Newton's second law gives F = ma, and acceleration has units m s⁻².$q$),
  ($q$Physical Quantities and Units$q$, $q$Why cannot 3 metres be added directly to 5 seconds in a physical equation?$q$, $q${"A":"Metres are always larger","B":"Seconds are vectors","C":"Both numbers are too small","D":"The terms have different dimensions"}$q$::jsonb, $q$D$q$, $q$Only quantities of the same dimension can be added meaningfully.$q$),
  ($q$Physical Quantities and Units$q$, $q$What is the SI unit of pressure in base units?$q$, $q${"A":"kg m⁻¹ s⁻²","B":"kg m s⁻¹","C":"kg m² s⁻²","D":"kg m⁻² s⁻¹"}$q$::jsonb, $q$A$q$, $q$Pressure = force/area = (kg m s⁻²)/m² = kg m⁻¹ s⁻².$q$),
  ($q$Physical Quantities and Units$q$, $q$Which conversion is correct for a length of 2.5 kilometres?$q$, $q${"A":"25 m","B":"2500 m","C":"250 m","D":"25 000 m"}$q$::jsonb, $q$B$q$, $q$One kilometre equals 1000 metres, so 2.5 × 1000 = 2500 m.$q$),
  ($q$Physical Quantities and Units$q$, $q$Why is density classified as a derived quantity?$q$, $q${"A":"It cannot be measured","B":"It has no unit","C":"It is mass divided by volume","D":"It is identical to temperature"}$q$::jsonb, $q$C$q$, $q$Density combines mass and length because volume has dimension length cubed.$q$),
  ($q$Physical Quantities and Units$q$, $q$An equation has energy on the left and force × distance on the right. Why is it dimensionally possible?$q$, $q${"A":"Force and energy have identical units","B":"Distance has no dimension","C":"Every multiplication is valid","D":"Both sides have units kg m² s⁻²"}$q$::jsonb, $q$D$q$, $q$Force × distance = (kg m s⁻²) × m = kg m² s⁻², the unit of energy.$q$),
  -- 2. Position, mass and weight (8)
  ($q$Position, Distance and Displacement$q$, $q$A walker travels 40 m east, then 40 m west. What is her displacement?$q$, $q${"A":"0 m","B":"40 m east","C":"80 m","D":"40 m west"}$q$::jsonb, $q$A$q$, $q$Her final position equals her initial position, so displacement is zero.$q$),
  ($q$Position, Distance and Displacement$q$, $q$For the same 40 m east then 40 m west trip, what total distance is covered?$q$, $q${"A":"0 m","B":"80 m","C":"40 m","D":"160 m"}$q$::jsonb, $q$B$q$, $q$Distance sums the path lengths: 40 + 40 = 80 m.$q$),
  ($q$Position, Distance and Displacement$q$, $q$Two students end at the same position after different routes. Which quantity must be the same for both if they started together?$q$, $q${"A":"Distance travelled","B":"Time taken","C":"Displacement","D":"Average speed"}$q$::jsonb, $q$C$q$, $q$Displacement depends only on starting and ending positions, not the route.$q$),
  ($q$Position, Distance and Displacement$q$, $q$A map position changes 3 km north and 4 km east. What is the magnitude of displacement?$q$, $q${"A":"7 km","B":"1 km","C":"12 km","D":"5 km"}$q$::jsonb, $q$D$q$, $q$The perpendicular components form a right triangle: √(3² + 4²) = 5 km.$q$),
  ($q$Mass and Weight$q$, $q$A sealed object is taken from Earth to the Moon. What happens to its mass?$q$, $q${"A":"It stays the same","B":"It becomes zero","C":"It doubles","D":"It changes with gravity"}$q$::jsonb, $q$A$q$, $q$Mass measures matter or inertia and does not depend on local gravity.$q$),
  ($q$Mass and Weight$q$, $q$A 5 kg bag is in a place where g = 10 N/kg. What is its weight?$q$, $q${"A":"0.5 N","B":"50 N","C":"5 N","D":"500 N"}$q$::jsonb, $q$B$q$, $q$Weight = mg = 5 kg × 10 N/kg = 50 N.$q$),
  ($q$Mass and Weight$q$, $q$Which quantity changes if an astronaut moves to a place with weaker gravity?$q$, $q${"A":"Number of atoms","B":"Inertial mass","C":"Weight","D":"Amount of matter"}$q$::jsonb, $q$C$q$, $q$Weight is gravitational force, W = mg, and falls when g decreases.$q$),
  ($q$Mass and Weight$q$, $q$Why is a spring balance suitable for measuring weight?$q$, $q${"A":"It counts molecules","B":"It measures volume","C":"It gives a mass independent of gravity","D":"Its extension responds to force"}$q$::jsonb, $q$D$q$, $q$A spring extends in response to the object's gravitational force.$q$),
  -- 3. Fluids (8)
  ($q$Density and Fluids at Rest$q$, $q$A solid has mass 300 g and volume 100 cm³. What is its density?$q$, $q${"A":"3 g/cm³","B":"0.33 g/cm³","C":"30 g/cm³","D":"300 g/cm³"}$q$::jsonb, $q$A$q$, $q$Density = mass/volume = 300/100 = 3 g/cm³.$q$),
  ($q$Density and Fluids at Rest$q$, $q$Why does water pressure increase with depth in a lake?$q$, $q${"A":"Water is less dense deeper down","B":"A deeper point supports a taller water column","C":"Gravity disappears at the surface","D":"The lake becomes wider"}$q$::jsonb, $q$B$q$, $q$Hydrostatic pressure depends on the height of fluid above the point: p = ρgh.$q$),
  ($q$Density and Fluids at Rest$q$, $q$At 2 m depth in water of density 1000 kg/m³, with g = 10 m/s², what is the pressure due to the water?$q$, $q${"A":"200 Pa","B":"2000 Pa","C":"20 000 Pa","D":"200 000 Pa"}$q$::jsonb, $q$C$q$, $q$p = ρgh = 1000 × 10 × 2 = 20 000 Pa.$q$),
  ($q$Density and Fluids at Rest$q$, $q$A floating block displaces water weighing 8 N. What is the block's weight?$q$, $q${"A":"4 N","B":"16 N","C":"80 N","D":"8 N"}$q$::jsonb, $q$D$q$, $q$For floating equilibrium, upthrust equals block weight and equals the displaced fluid's weight.$q$),
  ($q$Density and Fluids at Rest$q$, $q$An object immersed in water weighs less on a balance. What causes the reduction?$q$, $q${"A":"Upward buoyant force","B":"Loss of the object's mass","C":"An increase in gravity","D":"A change in its chemical formula"}$q$::jsonb, $q$A$q$, $q$The fluid exerts an upthrust opposing the object's weight.$q$),
  ($q$Density and Fluids at Rest$q$, $q$Why may a large hollow steel boat float while a solid steel block sinks?$q$, $q${"A":"The boat contains no steel","B":"The boat's average density, including enclosed air, can be less than water","C":"Steel loses all weight in water","D":"Air increases gravity"}$q$::jsonb, $q$B$q$, $q$The hull displaces enough water that the combined boat-and-air average density is low enough to float.$q$),
  ($q$Density and Fluids at Rest$q$, $q$Two points lie at the same depth in a connected liquid at rest. How do their pressures compare?$q$, $q${"A":"The wider side has higher pressure","B":"The narrower side has higher pressure","C":"They have equal pressure","D":"Pressure is always zero"}$q$::jsonb, $q$C$q$, $q$At equal depth in the same connected fluid, hydrostatic pressure is the same.$q$),
  ($q$Density and Fluids at Rest$q$, $q$A body displaces 0.002 m³ of water. With water density 1000 kg/m³ and g = 10 m/s², what upthrust acts on it?$q$, $q${"A":"2 N","B":"200 N","C":"2000 N","D":"20 N"}$q$::jsonb, $q$D$q$, $q$Upthrust = ρgV = 1000 × 10 × 0.002 = 20 N.$q$),
  -- 4. Motion, speed and acceleration (16)
  ($q$Motion and Forces$q$, $q$A stone tied to a string moves around a fixed centre. What force keeps changing its direction?$q$, $q${"A":"An inward centripetal force","B":"An outward gravitational force","C":"A force along its motion only","D":"No force at all"}$q$::jsonb, $q$A$q$, $q$Circular motion requires an inward resultant force to change velocity direction.$q$),
  ($q$Motion and Forces$q$, $q$Why does a moving bicycle eventually stop if the rider stops pedalling on level ground?$q$, $q${"A":"Inertia vanishes","B":"Resistive forces such as friction oppose motion","C":"Its mass becomes negative","D":"Gravity acts only forward"}$q$::jsonb, $q$B$q$, $q$Friction and air resistance remove kinetic energy and slow the bicycle.$q$),
  ($q$Motion and Forces$q$, $q$Which is a non-contact force?$q$, $q${"A":"Friction","B":"Tension","C":"Gravitational attraction","D":"A push by a hand"}$q$::jsonb, $q$C$q$, $q$Gravity acts across space without objects touching.$q$),
  ($q$Motion and Forces$q$, $q$Why do streamlined vehicles use less energy at high speed?$q$, $q${"A":"They have no mass","B":"They eliminate gravity","C":"They make air stationary","D":"They reduce drag from the air"}$q$::jsonb, $q$D$q$, $q$Streamlining reduces resistive fluid force, so less work is needed against it.$q$),
  ($q$Speed and Velocity$q$, $q$A bus travels 150 km in 3 hours. What is its average speed?$q$, $q${"A":"50 km/h","B":"450 km/h","C":"153 km/h","D":"0.02 km/h"}$q$::jsonb, $q$A$q$, $q$Average speed = total distance/total time = 150/3 = 50 km/h.$q$),
  ($q$Speed and Velocity$q$, $q$A runner completes one full circular lap and returns to the start. What is average velocity for the lap?$q$, $q${"A":"Equal to average speed","B":"Zero","C":"One lap per second","D":"Always directed north"}$q$::jsonb, $q$B$q$, $q$Average velocity = displacement/time; the lap has zero net displacement.$q$),
  ($q$Speed and Velocity$q$, $q$Which change can occur even if a car's speed stays constant?$q$, $q${"A":"Its mass must change","B":"Time stops","C":"Its velocity changes when it turns","D":"Distance becomes zero"}$q$::jsonb, $q$C$q$, $q$Velocity includes direction, so a turn changes velocity without changing speed.$q$),
  ($q$Speed and Velocity$q$, $q$A student walks 60 m east in 20 s. What is her average velocity?$q$, $q${"A":"1200 m/s east","B":"40 m/s west","C":"0.33 m/s east","D":"3 m/s east"}$q$::jsonb, $q$D$q$, $q$Average velocity = displacement/time = 60/20 = 3 m/s east.$q$),
  ($q$Rectilinear Acceleration$q$, $q$A car's velocity increases from 4 m/s to 16 m/s in 3 s. What is its acceleration?$q$, $q${"A":"4 m/s²","B":"12 m/s²","C":"6 m/s²","D":"20 m/s²"}$q$::jsonb, $q$A$q$, $q$a = Δv/t = (16 − 4)/3 = 4 m/s².$q$),
  ($q$Rectilinear Acceleration$q$, $q$A bicycle moving at 10 m/s decelerates uniformly at 2 m/s². How long until it stops?$q$, $q${"A":"2 s","B":"5 s","C":"8 s","D":"20 s"}$q$::jsonb, $q$B$q$, $q$From v = u + at, 0 = 10 − 2t, so t = 5 s.$q$),
  ($q$Rectilinear Acceleration$q$, $q$A ball starts from rest and accelerates uniformly at 3 m/s² for 4 s. What speed does it reach?$q$, $q${"A":"7 m/s","B":"1.3 m/s","C":"12 m/s","D":"24 m/s"}$q$::jsonb, $q$C$q$, $q$v = u + at = 0 + 3 × 4 = 12 m/s.$q$),
  ($q$Rectilinear Acceleration$q$, $q$An object starts from rest with acceleration 2 m/s² for 5 s. What distance does it cover?$q$, $q${"A":"10 m","B":"50 m","C":"5 m","D":"25 m"}$q$::jsonb, $q$D$q$, $q$s = ut + ½at² = 0 + ½ × 2 × 5² = 25 m.$q$),
  ($q$Rectilinear Acceleration$q$, $q$Ignoring air resistance, what is the acceleration of a freely falling stone near Earth's surface?$q$, $q${"A":"Approximately constant downward","B":"Zero after release","C":"Increasing with the stone's mass","D":"Constant upward"}$q$::jsonb, $q$A$q$, $q$Near the surface, free fall has approximately constant acceleration g toward Earth.$q$),
  ($q$Rectilinear Acceleration$q$, $q$A car moves at constant velocity along a straight road. What is its acceleration?$q$, $q${"A":"Equal to speed","B":"Zero","C":"Increasing","D":"Always 10 m/s²"}$q$::jsonb, $q$B$q$, $q$Acceleration is change in velocity per time; constant velocity means no change.$q$),
  ($q$Rectilinear Acceleration$q$, $q$A train slows from 20 m/s to 8 m/s in 4 s. What is its acceleration, taking forward as positive?$q$, $q${"A":"+3 m/s²","B":"−12 m/s²","C":"−3 m/s²","D":"+7 m/s²"}$q$::jsonb, $q$C$q$, $q$a = (v − u)/t = (8 − 20)/4 = −3 m/s².$q$),
  ($q$Rectilinear Acceleration$q$, $q$A ball is thrown vertically upward. At its highest point, what is true before it falls?$q$, $q${"A":"Both velocity and acceleration are zero","B":"Velocity is upward and acceleration zero","C":"Velocity is downward and acceleration upward","D":"Velocity is zero but acceleration is downward"}$q$::jsonb, $q$D$q$, $q$Instantaneous speed is zero at the top, but gravity continues to accelerate it downward.$q$),
  -- 5. Scalars and vectors (8)
  ($q$Scalars and Vectors$q$, $q$Which quantity must include a direction to be fully stated?$q$, $q${"A":"Displacement","B":"Temperature","C":"Energy","D":"Mass"}$q$::jsonb, $q$A$q$, $q$Displacement is a vector, so both magnitude and direction are required.$q$),
  ($q$Scalars and Vectors$q$, $q$A force of 6 N east and 8 N north act together. What is the resultant magnitude?$q$, $q${"A":"14 N","B":"10 N","C":"2 N","D":"48 N"}$q$::jsonb, $q$B$q$, $q$Perpendicular components give R = √(6² + 8²) = 10 N.$q$),
  ($q$Scalars and Vectors$q$, $q$A 12 N east force and a 5 N west force act on a body. What is the resultant?$q$, $q${"A":"17 N east","B":"7 N west","C":"7 N east","D":"60 N east"}$q$::jsonb, $q$C$q$, $q$Opposite forces subtract: 12 − 5 = 7 N east.$q$),
  ($q$Scalars and Vectors$q$, $q$Why can two nonzero forces produce zero resultant?$q$, $q${"A":"Forces are scalars","B":"One force loses its unit","C":"Gravity is absent","D":"They may be equal and opposite"}$q$::jsonb, $q$D$q$, $q$Equal opposite vectors cancel when added.$q$),
  ($q$Scalars and Vectors$q$, $q$A 10 N force makes 60° with the horizontal. What is its horizontal component? Use cos 60° = 0.5.$q$, $q${"A":"5 N","B":"10 N","C":"20 N","D":"0.5 N"}$q$::jsonb, $q$A$q$, $q$Horizontal component = F cos θ = 10 × 0.5 = 5 N.$q$),
  ($q$Scalars and Vectors$q$, $q$Which pair are both scalar quantities?$q$, $q${"A":"Velocity and force","B":"Speed and energy","C":"Displacement and mass","D":"Acceleration and time"}$q$::jsonb, $q$B$q$, $q$Speed and energy have magnitude only; the other pairs include a vector.$q$),
  ($q$Scalars and Vectors$q$, $q$A boat travels 3 km east then 4 km north. Which statement is correct?$q$, $q${"A":"Distance and displacement are both 7 km","B":"Distance is 5 km, displacement 7 km","C":"Distance is 7 km, displacement magnitude 5 km","D":"Distance and displacement are both 5 km"}$q$::jsonb, $q$C$q$, $q$Path length is 3 + 4 = 7 km; straight-line displacement is √(3² + 4²) = 5 km.$q$),
  ($q$Scalars and Vectors$q$, $q$What is the resultant of two perpendicular 5 N forces?$q$, $q${"A":"0 N","B":"5 N","C":"10 N","D":"5√2 N"}$q$::jsonb, $q$D$q$, $q$Pythagoras gives √(5² + 5²) = 5√2 N.$q$),
  -- 6. Equilibrium and moments (8)
  ($q$Equilibrium of Forces$q$, $q$A 10 N force acts 0.4 m from a pivot. What is its turning moment?$q$, $q${"A":"4 N m","B":"25 N m","C":"10.4 N m","D":"0.04 N m"}$q$::jsonb, $q$A$q$, $q$Moment = force × perpendicular distance = 10 × 0.4 = 4 N m.$q$),
  ($q$Equilibrium of Forces$q$, $q$A balanced beam has 6 N at 2 m to the left of a pivot. What force at 3 m to the right balances it?$q$, $q${"A":"9 N","B":"4 N","C":"6 N","D":"12 N"}$q$::jsonb, $q$B$q$, $q$Equal moments require 6 × 2 = F × 3, so F = 4 N.$q$),
  ($q$Equilibrium of Forces$q$, $q$For a rigid body at rest, what must be true of its net force and net moment?$q$, $q${"A":"Force zero, moment nonzero","B":"Force nonzero, moment zero","C":"Both zero","D":"Both necessarily positive"}$q$::jsonb, $q$C$q$, $q$Translational and rotational equilibrium require zero resultant force and moment.$q$),
  ($q$Equilibrium of Forces$q$, $q$Why is a wide, low base useful for a tall storage tank?$q$, $q${"A":"It raises the centre of gravity","B":"It removes the tank's mass","C":"It increases the force of gravity","D":"It makes tipping less likely"}$q$::jsonb, $q$D$q$, $q$A wider base and lower centre of gravity keep the weight line within the base more easily.$q$),
  ($q$Equilibrium of Forces$q$, $q$A door is easier to open when pushed far from its hinges. Why?$q$, $q${"A":"The same force produces a larger moment","B":"The door loses mass","C":"Air resistance disappears","D":"The hinge moves away"}$q$::jsonb, $q$A$q$, $q$Moment equals force times perpendicular distance from the hinge.$q$),
  ($q$Equilibrium of Forces$q$, $q$A 20 N load is held by two equal vertical supports. What is the force in each support?$q$, $q${"A":"20 N","B":"10 N","C":"40 N","D":"5 N"}$q$::jsonb, $q$B$q$, $q$The supports share the 20 N load equally, so each carries 20/2 = 10 N.$q$),
  ($q$Equilibrium of Forces$q$, $q$When does a body begin to topple?$q$, $q${"A":"Whenever its mass rises","B":"Whenever friction exists","C":"When the line of action of weight falls outside its base","D":"Whenever it is taller than 1 m"}$q$::jsonb, $q$C$q$, $q$Weight then creates an unbalanced overturning moment about the base edge.$q$),
  ($q$Equilibrium of Forces$q$, $q$Two equal parallel forces act in opposite directions at different points. What effect can they produce?$q$, $q${"A":"Pure translation only","B":"Zero force and zero moment always","C":"A change in mass","D":"A turning couple"}$q$::jsonb, $q$D$q$, $q$The forces cancel translationally but create a nonzero rotational moment.$q$),
  -- 7. Oscillations and Newton's laws (16)
  ($q$Simple Harmonic Motion$q$, $q$A pendulum makes 20 complete oscillations in 40 s. What is its period?$q$, $q${"A":"2 s","B":"0.5 s","C":"20 s","D":"800 s"}$q$::jsonb, $q$A$q$, $q$Period = total time/oscillations = 40/20 = 2 s.$q$),
  ($q$Simple Harmonic Motion$q$, $q$An oscillator has period 0.25 s. What is its frequency?$q$, $q${"A":"0.25 Hz","B":"4 Hz","C":"25 Hz","D":"40 Hz"}$q$::jsonb, $q$B$q$, $q$f = 1/T = 1/0.25 = 4 Hz.$q$),
  ($q$Simple Harmonic Motion$q$, $q$Where is the speed of an ideal oscillating mass greatest?$q$, $q${"A":"At either extreme","B":"Only when stopped","C":"At the equilibrium position","D":"At every point equally"}$q$::jsonb, $q$C$q$, $q$Potential energy is smallest and kinetic energy greatest at equilibrium.$q$),
  ($q$Simple Harmonic Motion$q$, $q$In simple harmonic motion, how does acceleration relate to displacement from equilibrium?$q$, $q${"A":"It is always in the same direction","B":"It is always zero","C":"It depends only on mass","D":"It is proportional and directed toward equilibrium"}$q$::jsonb, $q$D$q$, $q$SHM has restoring acceleration a = −ω²x.$q$),
  ($q$Simple Harmonic Motion$q$, $q$Why can a small periodic force produce a large oscillation near resonance?$q$, $q${"A":"Its frequency is close to the system's natural frequency","B":"Gravity has ended","C":"The object's mass is zero","D":"Energy conservation fails"}$q$::jsonb, $q$A$q$, $q$Energy is transferred efficiently when driving and natural frequencies are close.$q$),
  ($q$Simple Harmonic Motion$q$, $q$What does amplitude measure in an oscillation?$q$, $q${"A":"Total distance in a year","B":"Maximum displacement from equilibrium","C":"Time for one cycle","D":"Number of cycles each second"}$q$::jsonb, $q$B$q$, $q$Amplitude is the greatest distance from the equilibrium position.$q$),
  ($q$Simple Harmonic Motion$q$, $q$An oscillator completes 15 cycles in 5 s. What is its frequency?$q$, $q${"A":"0.33 Hz","B":"5 Hz","C":"3 Hz","D":"75 Hz"}$q$::jsonb, $q$C$q$, $q$Frequency = cycles/time = 15/5 = 3 Hz.$q$),
  ($q$Simple Harmonic Motion$q$, $q$In ideal SHM, where is displacement greatest in magnitude?$q$, $q${"A":"At equilibrium","B":"At every position equally","C":"Only midway to equilibrium","D":"At the two turning points"}$q$::jsonb, $q$D$q$, $q$The turning points lie one amplitude from equilibrium.$q$),
  ($q$Newton's Laws of Motion$q$, $q$A passenger lurches forward when a bus brakes suddenly. Which law explains the tendency to keep moving?$q$, $q${"A":"Newton's first law","B":"Coulomb's law","C":"Hooke's law","D":"Boyle's law"}$q$::jsonb, $q$A$q$, $q$Inertia makes the passenger tend to maintain the previous forward velocity.$q$),
  ($q$Newton's Laws of Motion$q$, $q$A net force of 12 N acts on a 3 kg trolley. What is its acceleration?$q$, $q${"A":"36 m/s²","B":"4 m/s²","C":"9 m/s²","D":"0.25 m/s²"}$q$::jsonb, $q$B$q$, $q$F = ma, so a = F/m = 12/3 = 4 m/s².$q$),
  ($q$Newton's Laws of Motion$q$, $q$Why does a rocket move forward as gas is expelled backward?$q$, $q${"A":"The gas has no momentum","B":"A vacuum pulls the rocket","C":"The gas exerts an opposite force on the rocket","D":"Gravity changes direction"}$q$::jsonb, $q$C$q$, $q$Newton's third law pairs the rocket's force on gas with an equal opposite force on the rocket.$q$),
  ($q$Newton's Laws of Motion$q$, $q$A 2 kg ball moves at 5 m/s. What is its momentum?$q$, $q${"A":"2.5 kg m/s","B":"7 kg m/s","C":"25 kg m/s","D":"10 kg m/s"}$q$::jsonb, $q$D$q$, $q$Momentum p = mv = 2 × 5 = 10 kg m/s.$q$),
  ($q$Newton's Laws of Motion$q$, $q$A force of 5 N acts for 2 s. What impulse does it deliver?$q$, $q${"A":"10 N s","B":"2.5 N s","C":"7 N s","D":"25 N s"}$q$::jsonb, $q$A$q$, $q$Impulse = force × time = 5 × 2 = 10 N s.$q$),
  ($q$Newton's Laws of Motion$q$, $q$Why does a seat belt reduce injury in a sudden stop?$q$, $q${"A":"It removes the passenger's mass","B":"It extends stopping time and reduces average force","C":"It raises momentum after stopping","D":"It reverses gravity"}$q$::jsonb, $q$B$q$, $q$For the same momentum change, a longer stopping interval means smaller average force.$q$),
  ($q$Newton's Laws of Motion$q$, $q$Two bodies of different mass experience the same net force. Which accelerates more?$q$, $q${"A":"The heavier body","B":"Both equally","C":"The lighter body","D":"Neither can accelerate"}$q$::jsonb, $q$C$q$, $q$From a = F/m, acceleration is greater when mass is smaller.$q$),
  ($q$Newton's Laws of Motion$q$, $q$Why do action and reaction forces not cancel each other on one object?$q$, $q${"A":"They act at different times","B":"Only one is real","C":"They are unequal","D":"They act on different objects"}$q$::jsonb, $q$D$q$, $q$Third-law forces are equal and opposite but act on separate bodies.$q$),
  -- 8. Work, energy and power (8)
  ($q$Work, Energy and Power$q$, $q$A 20 N force moves an object 3 m in its direction. How much work is done?$q$, $q${"A":"60 J","B":"6.7 J","C":"23 J","D":"600 J"}$q$::jsonb, $q$A$q$, $q$Work = force × displacement along the force = 20 × 3 = 60 J.$q$),
  ($q$Work, Energy and Power$q$, $q$A machine does 600 J of work in 3 s. What is its power?$q$, $q${"A":"1800 W","B":"200 W","C":"603 W","D":"2 W"}$q$::jsonb, $q$B$q$, $q$Power = work/time = 600/3 = 200 W.$q$),
  ($q$Work, Energy and Power$q$, $q$A 2 kg object moves at 4 m/s. What is its kinetic energy?$q$, $q${"A":"4 J","B":"8 J","C":"16 J","D":"32 J"}$q$::jsonb, $q$C$q$, $q$Kinetic energy = ½mv² = ½ × 2 × 4² = 16 J.$q$),
  ($q$Work, Energy and Power$q$, $q$A 3 kg object is lifted 2 m where g = 10 m/s². What potential energy does it gain?$q$, $q${"A":"15 J","B":"30 J","C":"6 J","D":"60 J"}$q$::jsonb, $q$D$q$, $q$Gain in gravitational potential energy = mgh = 3 × 10 × 2 = 60 J.$q$),
  ($q$Work, Energy and Power$q$, $q$When a falling object has no air resistance, what happens to its gravitational potential energy?$q$, $q${"A":"It converts into kinetic energy","B":"It vanishes without trace","C":"It stays constant while height falls","D":"It becomes mass"}$q$::jsonb, $q$A$q$, $q$As height decreases, potential energy decreases while kinetic energy increases.$q$),
  ($q$Work, Energy and Power$q$, $q$Why can a machine's useful output energy be less than its input energy?$q$, $q${"A":"Energy is destroyed","B":"Some energy is transferred to heat and sound","C":"Input energy has no unit","D":"Output power is always zero"}$q$::jsonb, $q$B$q$, $q$Friction and other losses transfer energy into less useful forms; total energy remains conserved.$q$),
  ($q$Work, Energy and Power$q$, $q$A machine receives 100 J and provides 80 J of useful output. What is its efficiency?$q$, $q${"A":"20%","B":"125%","C":"80%","D":"8000%"}$q$::jsonb, $q$C$q$, $q$Efficiency = useful output/input × 100 = 80/100 × 100 = 80%.$q$),
  ($q$Work, Energy and Power$q$, $q$A porter carries a bag horizontally at constant height. How much work does the upward supporting force do on the bag?$q$, $q${"A":"Equal to bag weight × distance","B":"Greater than total energy","C":"Always negative","D":"Zero"}$q$::jsonb, $q$D$q$, $q$The supporting force is vertical while displacement is horizontal, so its work Fd cos 90° is zero.$q$),
  -- 9. Heat and temperature (8)
  ($q$Heat and Temperature$q$, $q$Two metal blocks at different temperatures touch. In which direction does heat flow spontaneously?$q$, $q${"A":"From hotter to cooler","B":"From cooler to hotter only","C":"Only if both have equal mass","D":"In no direction"}$q$::jsonb, $q$A$q$, $q$Heat transfers spontaneously from higher to lower temperature until thermal equilibrium.$q$),
  ($q$Heat and Temperature$q$, $q$Why does a metal spoon in hot tea feel warmer than a wooden spoon?$q$, $q${"A":"Metal has no heat capacity","B":"Metal conducts heat to the hand faster","C":"Wood creates cold energy","D":"Metal has more mass in every case"}$q$::jsonb, $q$B$q$, $q$Metals conduct thermal energy much more effectively than wood.$q$),
  ($q$Heat and Temperature$q$, $q$A black surface warms quickly in sunlight mainly because it does what?$q$, $q${"A":"Reflects all radiation","B":"Stops convection","C":"Absorbs a high fraction of incident radiation","D":"Has no heat capacity"}$q$::jsonb, $q$C$q$, $q$Dark surfaces generally absorb more incident radiant energy than shiny light surfaces.$q$),
  ($q$Heat and Temperature$q$, $q$Which heat-transfer process can carry energy through empty space?$q$, $q${"A":"Conduction","B":"Convection","C":"Diffusion of liquid","D":"Radiation"}$q$::jsonb, $q$D$q$, $q$Electromagnetic thermal radiation does not require a material medium.$q$),
  ($q$Heat and Temperature$q$, $q$Why does warm air rise above a heater?$q$, $q${"A":"It expands, becomes less dense and is buoyed upward","B":"Its molecules stop moving","C":"It becomes heavier than cooler air","D":"The heater removes gravity"}$q$::jsonb, $q$A$q$, $q$Heating expands air; at lower density, surrounding cooler air pushes it upward.$q$),
  ($q$Heat and Temperature$q$, $q$A metal rod lengthens on heating. What microscopic change explains this?$q$, $q${"A":"Atoms become larger nuclei","B":"Particles vibrate more and their average spacing rises","C":"Every atom becomes a gas","D":"Mass is created"}$q$::jsonb, $q$B$q$, $q$Greater particle motion increases the average separation in the solid.$q$),
  ($q$Heat and Temperature$q$, $q$A room is at 27°C. What is its approximate absolute temperature?$q$, $q${"A":"27 K","B":"246 K","C":"300 K","D":"573 K"}$q$::jsonb, $q$C$q$, $q$Kelvin temperature is Celsius temperature plus about 273: 27 + 273 = 300 K.$q$),
  ($q$Heat and Temperature$q$, $q$Why are expansion gaps left in long metal bridges?$q$, $q${"A":"To make them lighter","B":"To increase friction","C":"To prevent conduction","D":"To allow thermal expansion without damage"}$q$::jsonb, $q$D$q$, $q$A hot bridge lengthens; gaps reduce buckling or stress.$q$),
  -- 10. Gas laws, heat capacity and phase changes (16)
  ($q$Gas Laws$q$, $q$A gas at constant temperature occupies 4 L at 100 kPa. What volume will it occupy at 200 kPa?$q$, $q${"A":"2 L","B":"8 L","C":"4 L","D":"0.5 L"}$q$::jsonb, $q$A$q$, $q$Boyle's law gives P₁V₁ = P₂V₂, so V₂ = 100 × 4/200 = 2 L.$q$),
  ($q$Gas Laws$q$, $q$Why must temperature be in kelvin when applying Charles' law?$q$, $q${"A":"Kelvin values are always smaller","B":"Gas volume is proportional to absolute temperature","C":"Celsius measures pressure","D":"Kelvin removes the gas mass"}$q$::jsonb, $q$B$q$, $q$Charles' law states V/T is constant with T measured from absolute zero.$q$),
  ($q$Gas Laws$q$, $q$A gas expands from 2 L to 3 L at constant pressure while initially at 300 K. What final temperature is expected?$q$, $q${"A":"200 K","B":"450°C","C":"450 K","D":"600 K"}$q$::jsonb, $q$C$q$, $q$V/T is constant, so T₂ = 300 × 3/2 = 450 K.$q$),
  ($q$Gas Laws$q$, $q$A sealed rigid gas container is warmed. Why does its pressure rise?$q$, $q${"A":"Gas particles lose speed","B":"Container volume doubles","C":"The number of particles becomes zero","D":"Faster particles strike the walls more forcefully"}$q$::jsonb, $q$D$q$, $q$Heating increases molecular kinetic energy and momentum transfer to the fixed walls.$q$),
  ($q$Gas Laws$q$, $q$At constant temperature, the volume of a fixed mass of gas is halved. What happens to pressure?$q$, $q${"A":"It doubles","B":"It halves","C":"It stays fixed","D":"It becomes zero"}$q$::jsonb, $q$A$q$, $q$Boyle's law gives pressure inversely proportional to volume.$q$),
  ($q$Gas Laws$q$, $q$A fixed-volume gas has pressure 100 kPa at 300 K. What is its pressure at 600 K?$q$, $q${"A":"50 kPa","B":"200 kPa","C":"300 kPa","D":"600 kPa"}$q$::jsonb, $q$B$q$, $q$At constant volume, P/T is constant: P₂ = 100 × 600/300 = 200 kPa.$q$),
  ($q$Gas Laws$q$, $q$Why does a bicycle tyre pressure rise after a long ride?$q$, $q${"A":"The rubber gains mass","B":"The air turns solid","C":"Warmer air inside exerts greater pressure","D":"The wheel becomes weightless"}$q$::jsonb, $q$C$q$, $q$Rising air temperature increases molecular collisions and pressure in the nearly fixed volume.$q$),
  ($q$Gas Laws$q$, $q$Which relationship applies to a fixed mass of ideal gas if pressure, volume and temperature may all change?$q$, $q${"A":"P + V = T","B":"PV = 0","C":"P/V = constant at all temperatures","D":"PV/T = constant"}$q$::jsonb, $q$D$q$, $q$The combined gas law gives PV/T constant when amount of gas is fixed.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$How much heat warms 2 kg of water by 3°C if c = 4200 J kg⁻¹ °C⁻¹?$q$, $q${"A":"25 200 J","B":"2800 J","C":"6300 J","D":"8400 J"}$q$::jsonb, $q$A$q$, $q$Q = mcΔT = 2 × 4200 × 3 = 25 200 J.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$A 5 kg object needs 10 000 J for a 2°C rise. What is its specific heat capacity?$q$, $q${"A":"500 J kg⁻¹ °C⁻¹","B":"1000 J kg⁻¹ °C⁻¹","C":"5000 J kg⁻¹ °C⁻¹","D":"20 000 J kg⁻¹ °C⁻¹"}$q$::jsonb, $q$B$q$, $q$c = Q/(mΔT) = 10 000/(5 × 2) = 1000 J kg⁻¹ °C⁻¹.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$Why can ice at 0°C absorb heat without becoming warmer while melting?$q$, $q${"A":"Its mass becomes zero","B":"Its thermometer is broken","C":"Energy changes its state rather than temperature","D":"It releases all energy at once"}$q$::jsonb, $q$C$q$, $q$Latent heat breaks the solid structure while temperature stays at the melting point.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$A 0.5 kg material melts with latent heat of fusion 200 kJ/kg. How much energy is needed?$q$, $q${"A":"400 kJ","B":"200 kJ","C":"50 kJ","D":"100 kJ"}$q$::jsonb, $q$D$q$, $q$Q = mL = 0.5 × 200 = 100 kJ.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$Why can evaporation cool the liquid left behind?$q$, $q${"A":"Higher-energy molecules preferentially escape","B":"Evaporation creates negative energy","C":"The liquid gains mass","D":"Only cold molecules escape"}$q$::jsonb, $q$A$q$, $q$Escaping energetic molecules lower the average kinetic energy of the remainder.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$How does boiling differ from evaporation?$q$, $q${"A":"Boiling occurs only at a surface","B":"Boiling forms vapour throughout the liquid at its boiling point","C":"Evaporation needs a fixed boiling point","D":"Evaporation occurs only in a vacuum"}$q$::jsonb, $q$B$q$, $q$At boiling, vapour bubbles form within the liquid, whereas evaporation occurs at the surface.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$A dry day speeds evaporation compared with a humid day mainly because what?$q$, $q${"A":"Gravity is smaller","B":"Water stops boiling","C":"The air can accept more water vapour","D":"The liquid has no temperature"}$q$::jsonb, $q$C$q$, $q$Lower ambient vapour content increases the net escape of molecules from the liquid.$q$),
  ($q$Heat Capacity and Latent Heat$q$, $q$A sample releases heat as vapour condenses to liquid at constant temperature. Which energy is released?$q$, $q${"A":"Kinetic energy of the container only","B":"Electrical energy","C":"Gravitational potential energy","D":"Latent heat of vaporization"}$q$::jsonb, $q$D$q$, $q$Condensation releases the latent energy absorbed during vaporization.$q$),
  -- 11. Waves and sound (16)
  ($q$Wave Motion$q$, $q$A wave has frequency 5 Hz and wavelength 2 m. What is its speed?$q$, $q${"A":"10 m/s","B":"2.5 m/s","C":"7 m/s","D":"0.4 m/s"}$q$::jsonb, $q$A$q$, $q$v = fλ = 5 × 2 = 10 m/s.$q$),
  ($q$Wave Motion$q$, $q$What is the period of a 4 Hz wave?$q$, $q${"A":"4 s","B":"0.25 s","C":"2 s","D":"16 s"}$q$::jsonb, $q$B$q$, $q$T = 1/f = 1/4 = 0.25 s.$q$),
  ($q$Wave Motion$q$, $q$In a transverse wave, how do particle vibrations compare with the travel direction?$q$, $q${"A":"They are parallel","B":"They cease","C":"They are perpendicular","D":"They are always circular"}$q$::jsonb, $q$C$q$, $q$Transverse disturbances vibrate at right angles to the direction of propagation.$q$),
  ($q$Wave Motion$q$, $q$Sound in air is mainly what type of wave?$q$, $q${"A":"Transverse electromagnetic","B":"Stationary light","C":"A vacuum wave","D":"Longitudinal mechanical"}$q$::jsonb, $q$D$q$, $q$Air particles oscillate parallel to the sound's direction, and a medium is needed.$q$),
  ($q$Wave Motion$q$, $q$Why does a wave bend around a doorway?$q$, $q${"A":"Diffraction spreads it beyond the opening","B":"Reflection eliminates it","C":"Its mass doubles","D":"The doorway generates gravity"}$q$::jsonb, $q$A$q$, $q$Diffraction is the spreading of waves around edges and through gaps.$q$),
  ($q$Wave Motion$q$, $q$Two waves overlap and their displacements add. What principle describes this?$q$, $q${"A":"Archimedes' principle","B":"Superposition","C":"Boyle's law","D":"Inertia"}$q$::jsonb, $q$B$q$, $q$Superposition states that the resultant displacement is the sum of component displacements.$q$),
  ($q$Wave Motion$q$, $q$A wave passes from one medium to another and changes speed. What property remains fixed for a steady source?$q$, $q${"A":"Wavelength","B":"Direction always","C":"Frequency","D":"Amplitude always"}$q$::jsonb, $q$C$q$, $q$Frequency is set by the source; speed and wavelength may change.$q$),
  ($q$Wave Motion$q$, $q$Why can destructive interference produce a quiet point?$q$, $q${"A":"The medium has vanished","B":"Energy is destroyed globally","C":"Both waves stop everywhere","D":"Opposite displacements cancel locally"}$q$::jsonb, $q$D$q$, $q$Out-of-phase waves can sum to near zero displacement at that point.$q$),
  ($q$Sound Waves$q$, $q$An echo returns 2 s after a sound is made. If sound speed is 340 m/s, how far away is the reflector?$q$, $q${"A":"340 m","B":"680 m","C":"170 m","D":"34 m"}$q$::jsonb, $q$A$q$, $q$Sound travels to the reflector and back: distance one way = vt/2 = 340 × 2/2 = 340 m.$q$),
  ($q$Sound Waves$q$, $q$What determines the pitch of a sound?$q$, $q${"A":"Amplitude","B":"Frequency","C":"Distance alone","D":"Loudness alone"}$q$::jsonb, $q$B$q$, $q$Higher vibration frequency is heard as higher pitch.$q$),
  ($q$Sound Waves$q$, $q$What mainly makes one musical note louder than another of the same pitch?$q$, $q${"A":"Lower frequency","B":"Longer wavelength only","C":"Greater amplitude","D":"Different speed in air"}$q$::jsonb, $q$C$q$, $q$Greater wave amplitude carries more intensity and is perceived as louder.$q$),
  ($q$Sound Waves$q$, $q$Why cannot a bell be heard through an ideal vacuum?$q$, $q${"A":"The bell loses mass","B":"Light blocks it","C":"Its frequency becomes zero","D":"Sound needs a medium"}$q$::jsonb, $q$D$q$, $q$Sound is a mechanical disturbance and needs particles to transfer vibrations.$q$),
  ($q$Sound Waves$q$, $q$Why is an echo distinct from reverberation?$q$, $q${"A":"An echo is a delayed separate reflection; reverberation is overlapping reflections","B":"An echo needs no surface","C":"Reverberation occurs only in vacuum","D":"Both are unrelated to reflection"}$q$::jsonb, $q$A$q$, $q$A sufficiently delayed reflection is heard separately; many short-delay reflections prolong the sound.$q$),
  ($q$Sound Waves$q$, $q$A string's frequency doubles while wave speed stays constant. What happens to its wavelength?$q$, $q${"A":"It doubles","B":"It halves","C":"It quadruples","D":"It stays the same"}$q$::jsonb, $q$B$q$, $q$Since v = fλ is constant, doubling f requires λ to halve.$q$),
  ($q$Sound Waves$q$, $q$Why can sound travel faster through steel than through air?$q$, $q${"A":"Steel contains no particles","B":"Air has no elasticity","C":"The medium's stiffness and particle coupling differ","D":"Steel makes frequency zero"}$q$::jsonb, $q$C$q$, $q$Speed depends on the medium's elastic and inertial properties, not just distance.$q$),
  ($q$Sound Waves$q$, $q$A tuning fork transfers vibration to a matching second fork. What phenomenon is most directly involved?$q$, $q${"A":"Total internal reflection","B":"Radioactivity","C":"Static electricity","D":"Resonance"}$q$::jsonb, $q$D$q$, $q$A fork with the same natural frequency responds strongly to the driving vibration.$q$),
  -- 12. Light and electromagnetic radiation (16)
  ($q$Light and Optics$q$, $q$An image in a plane mirror appears 2 m behind it when an object is 2 m in front. What is object-to-image distance?$q$, $q${"A":"4 m","B":"2 m","C":"1 m","D":"0 m"}$q$::jsonb, $q$A$q$, $q$The image is as far behind as the object is in front, so separation is 2 + 2 = 4 m.$q$),
  ($q$Light and Optics$q$, $q$Why does a straight straw appear bent in a glass of water?$q$, $q${"A":"Water magnifies its mass","B":"Light refracts at the water-air boundary","C":"The straw actually bends","D":"Light stops at the surface"}$q$::jsonb, $q$B$q$, $q$A speed change at the boundary bends light rays, shifting the apparent position.$q$),
  ($q$Light and Optics$q$, $q$A ray strikes a plane mirror at 30° to the normal. What is its angle of reflection?$q$, $q${"A":"60°","B":"90°","C":"30°","D":"15°"}$q$::jsonb, $q$C$q$, $q$The law of reflection sets angle of reflection equal to angle of incidence, measured from the normal.$q$),
  ($q$Light and Optics$q$, $q$What type of lens can focus parallel light rays to a real point?$q$, $q${"A":"A plane glass sheet","B":"A diverging lens","C":"An opaque lens","D":"A converging lens"}$q$::jsonb, $q$D$q$, $q$A converging lens brings parallel rays to its focal point.$q$),
  ($q$Light and Optics$q$, $q$Why can an optical fibre guide light around a bend?$q$, $q${"A":"Repeated total internal reflection keeps light in its core","B":"It converts light to sound","C":"Its core has zero refractive index","D":"Gravity traps light"}$q$::jsonb, $q$A$q$, $q$At the core boundary, suitable incidence angles produce total internal reflection.$q$),
  ($q$Light and Optics$q$, $q$When white light passes through a prism, why do colours separate?$q$, $q${"A":"All wavelengths travel identically in glass","B":"Different wavelengths refract by different amounts","C":"The prism creates new colours from nothing","D":"Only red light enters"}$q$::jsonb, $q$B$q$, $q$Dispersion occurs because refractive index varies with wavelength.$q$),
  ($q$Light and Optics$q$, $q$Which image is formed by a plane mirror?$q$, $q${"A":"Real and inverted","B":"Real and magnified","C":"Virtual and upright","D":"Always projected on a screen"}$q$::jsonb, $q$C$q$, $q$A plane mirror forms an upright virtual image that cannot be projected on a screen.$q$),
  ($q$Light and Optics$q$, $q$Light travels from glass into air at an angle above the critical angle. What happens at the boundary?$q$, $q${"A":"It stops existing","B":"It passes straight through","C":"Its frequency doubles","D":"Total internal reflection occurs"}$q$::jsonb, $q$D$q$, $q$Above the critical angle in a denser-to-rarer transition, the ray reflects back into glass.$q$),
  ($q$Electromagnetic Waves$q$, $q$Which radiation has the longest wavelength among these?$q$, $q${"A":"Radio waves","B":"Visible light","C":"X-rays","D":"Gamma rays"}$q$::jsonb, $q$A$q$, $q$Radio waves occupy the long-wavelength end of the electromagnetic spectrum.$q$),
  ($q$Electromagnetic Waves$q$, $q$What do all electromagnetic waves share in a vacuum?$q$, $q${"A":"The same frequency","B":"The same speed","C":"The same wavelength","D":"The same intensity"}$q$::jsonb, $q$B$q$, $q$All electromagnetic waves travel at speed c in vacuum despite differing wavelengths and frequencies.$q$),
  ($q$Electromagnetic Waves$q$, $q$Which radiation is useful for remote-control devices and heat sensing?$q$, $q${"A":"Gamma rays","B":"X-rays","C":"Infrared","D":"Ultraviolet"}$q$::jsonb, $q$C$q$, $q$Infrared radiation is commonly used in remote controls and thermal detection.$q$),
  ($q$Electromagnetic Waves$q$, $q$Why must prolonged exposure to strong ultraviolet radiation be limited?$q$, $q${"A":"It has no energy","B":"It always improves vision","C":"It becomes sound","D":"It can damage skin and cells"}$q$::jsonb, $q$D$q$, $q$High-energy ultraviolet photons can damage living tissue.$q$),
  ($q$Electromagnetic Waves$q$, $q$A wave's wavelength decreases in vacuum. What happens to its frequency?$q$, $q${"A":"It increases","B":"It decreases","C":"It stays zero","D":"It becomes independent of speed"}$q$::jsonb, $q$A$q$, $q$Since c = fλ is fixed in vacuum, smaller λ means larger f.$q$),
  ($q$Electromagnetic Waves$q$, $q$Which radiation is commonly used to image bones because it penetrates soft tissue more readily?$q$, $q${"A":"Radio","B":"X-ray","C":"Microwave","D":"Visible red"}$q$::jsonb, $q$B$q$, $q$X-rays pass through soft tissue more readily than dense bone, producing image contrast.$q$),
  ($q$Electromagnetic Waves$q$, $q$What distinguishes electromagnetic waves from sound in empty space?$q$, $q${"A":"They have no energy","B":"They are always audible","C":"They can propagate through vacuum","D":"They need air particles"}$q$::jsonb, $q$C$q$, $q$Electromagnetic fields can propagate without a material medium.$q$),
  ($q$Electromagnetic Waves$q$, $q$If an electromagnetic wave's frequency doubles in vacuum, what happens to its wavelength?$q$, $q${"A":"It doubles","B":"It quadruples","C":"It stays unchanged","D":"It halves"}$q$::jsonb, $q$D$q$, $q$With c constant, λ = c/f, so doubling f halves λ.$q$),
  -- 13. Gravitational and electric fields (16)
  ($q$Gravitational Fields$q$, $q$What does gravitational field strength measure?$q$, $q${"A":"Force per unit mass","B":"Mass per unit force","C":"Energy per unit time","D":"Charge per unit area"}$q$::jsonb, $q$A$q$, $q$Field strength g = F/m is the force experienced by each kilogram.$q$),
  ($q$Gravitational Fields$q$, $q$Why do two objects attract gravitationally even without contact?$q$, $q${"A":"Their temperatures match","B":"Each lies in the other's gravitational field","C":"They exchange electric charge","D":"They have identical masses"}$q$::jsonb, $q$B$q$, $q$Mass produces a field that exerts force on other masses at a distance.$q$),
  ($q$Gravitational Fields$q$, $q$A planet's radius stays fixed while its mass doubles. How does surface gravity change?$q$, $q${"A":"It halves","B":"It quadruples","C":"It doubles","D":"It becomes zero"}$q$::jsonb, $q$C$q$, $q$Surface g = GM/R², so doubling M at fixed R doubles g.$q$),
  ($q$Gravitational Fields$q$, $q$Two masses are moved twice as far apart. How does their gravitational force change?$q$, $q${"A":"It doubles","B":"It halves","C":"It quadruples","D":"It becomes one-quarter"}$q$::jsonb, $q$D$q$, $q$Inverse-square law gives F proportional to 1/r²; doubling r divides F by 4.$q$),
  ($q$Gravitational Fields$q$, $q$Why does a satellite remain in orbit rather than move in a straight line?$q$, $q${"A":"Gravity supplies inward acceleration","B":"There is no gravitational force in orbit","C":"Its mass disappears","D":"Air pushes it outward"}$q$::jsonb, $q$A$q$, $q$Gravity continuously bends the satellite's path toward Earth.$q$),
  ($q$Gravitational Fields$q$, $q$A 4 kg mass experiences 20 N gravitational force. What is the field strength?$q$, $q${"A":"80 N/kg","B":"5 N/kg","C":"16 N/kg","D":"0.2 N/kg"}$q$::jsonb, $q$B$q$, $q$g = F/m = 20/4 = 5 N/kg.$q$),
  ($q$Gravitational Fields$q$, $q$What makes a geostationary satellite appear fixed above one point on Earth's equator?$q$, $q${"A":"It has no velocity","B":"It moves opposite Earth's rotation","C":"Its orbital period and direction match Earth's rotation","D":"It orbits through the poles"}$q$::jsonb, $q$C$q$, $q$A geostationary orbit has Earth's rotation period and same rotational direction over the equator.$q$),
  ($q$Gravitational Fields$q$, $q$At twice Earth's centre-to-centre distance from a point mass, how does gravitational field strength compare?$q$, $q${"A":"Twice as strong","B":"Half as strong","C":"Four times as strong","D":"One-quarter as strong"}$q$::jsonb, $q$D$q$, $q$Field strength varies as 1/r², so doubling distance reduces it to one-quarter.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$A rubbed balloon attracts small neutral paper pieces. What first happens in the paper?$q$, $q${"A":"Charges redistribute slightly by polarization","B":"It becomes a permanent magnet","C":"Its nuclei vanish","D":"It loses all electrons"}$q$::jsonb, $q$A$q$, $q$The balloon's field shifts bound charges so the nearer side has opposite effective charge.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$Two identical positive charges are brought closer. How does their electric force change?$q$, $q${"A":"It becomes attractive","B":"Repulsion increases","C":"It becomes zero","D":"Their charges reverse"}$q$::jsonb, $q$B$q$, $q$Like charges repel, and Coulomb force increases as separation decreases.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$Why is an earthing wire useful on metal equipment?$q$, $q${"A":"It raises operating voltage","B":"It prevents all heating","C":"It provides a low-resistance path for fault charge","D":"It stores charge indefinitely"}$q$::jsonb, $q$C$q$, $q$Earthing directs fault current safely and helps protective devices operate.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$Two point charges are moved three times as far apart. What fraction of the original electrostatic force remains?$q$, $q${"A":"1/3","B":"3","C":"9","D":"1/9"}$q$::jsonb, $q$D$q$, $q$Coulomb's law gives F proportional to 1/r², so 3r gives F/9.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$What does electric potential difference of 6 V mean?$q$, $q${"A":"6 J of energy transferred per coulomb","B":"6 C flow each second always","C":"6 N acts on every object","D":"6 W is used regardless of current"}$q$::jsonb, $q$A$q$, $q$One volt is one joule per coulomb, so 6 V means 6 J/C.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$A capacitor stores 12 C when potential difference is 4 V. What is its capacitance?$q$, $q${"A":"48 F","B":"3 F","C":"16 F","D":"0.33 F"}$q$::jsonb, $q$B$q$, $q$C = Q/V = 12/4 = 3 F.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$Why does inserting a dielectric between capacitor plates increase capacitance?$q$, $q${"A":"It turns the plates into magnets","B":"It destroys the electric field","C":"Polarization reduces effective field for a given charge","D":"It adds a power source"}$q$::jsonb, $q$C$q$, $q$Dielectric polarization lowers voltage for the same stored charge, so C = Q/V rises.$q$),
  ($q$Electrostatics and Capacitance$q$, $q$What is the direction of electric field around an isolated positive point charge?$q$, $q${"A":"Circular only","B":"Toward the charge","C":"Random at every point","D":"Radially outward"}$q$::jsonb, $q$D$q$, $q$A positive test charge would be repelled away from the source charge.$q$),
  -- 14. Current electricity and circuits (16)
  ($q$Current Electricity$q$, $q$A charge of 24 C crosses a wire in 6 s. What is the current?$q$, $q${"A":"4 A","B":"144 A","C":"18 A","D":"0.25 A"}$q$::jsonb, $q$A$q$, $q$I = Q/t = 24/6 = 4 A.$q$),
  ($q$Current Electricity$q$, $q$Why do metals conduct electric current readily?$q$, $q${"A":"Their atoms are motionless","B":"They contain mobile electrons","C":"They have no resistance at all","D":"They contain only protons"}$q$::jsonb, $q$B$q$, $q$Mobile conduction electrons carry charge through the metal.$q$),
  ($q$Current Electricity$q$, $q$A resistor has 12 V across it and carries 3 A. What is its resistance?$q$, $q${"A":"36 Ω","B":"15 Ω","C":"4 Ω","D":"0.25 Ω"}$q$::jsonb, $q$C$q$, $q$R = V/I = 12/3 = 4 Ω.$q$),
  ($q$Current Electricity$q$, $q$A 6 Ω resistor carries 2 A. What power is dissipated?$q$, $q${"A":"3 W","B":"12 W","C":"18 W","D":"24 W"}$q$::jsonb, $q$D$q$, $q$P = I²R = 2² × 6 = 24 W.$q$),
  ($q$Current Electricity$q$, $q$What happens to a uniform wire's resistance if its length doubles without changing material or area?$q$, $q${"A":"It doubles","B":"It halves","C":"It becomes zero","D":"It quadruples"}$q$::jsonb, $q$A$q$, $q$R = ρL/A, so doubling L doubles R.$q$),
  ($q$Current Electricity$q$, $q$Which unit is used for electrical energy consumed by a household?$q$, $q${"A":"Kilowatt","B":"Kilowatt-hour","C":"Volt","D":"Ampere"}$q$::jsonb, $q$B$q$, $q$A kilowatt-hour is power × time, a unit of energy.$q$),
  ($q$Current Electricity$q$, $q$A 100 W lamp runs for 5 hours. How much energy does it use?$q$, $q${"A":"500 kWh","B":"5 kWh","C":"0.5 kWh","D":"0.02 kWh"}$q$::jsonb, $q$C$q$, $q$100 W = 0.1 kW, so energy = 0.1 × 5 = 0.5 kWh.$q$),
  ($q$Current Electricity$q$, $q$A cell's terminal voltage falls when it supplies a large current. What internal property contributes?$q$, $q${"A":"Infinite capacitance","B":"No charge carriers","C":"Zero emf","D":"Internal resistance"}$q$::jsonb, $q$D$q$, $q$Voltage is lost across internal resistance when current flows.$q$),
  ($q$Electric Circuits$q$, $q$Two resistors of 2 Ω and 3 Ω are connected in series. What is total resistance?$q$, $q${"A":"5 Ω","B":"1.2 Ω","C":"6 Ω","D":"0.5 Ω"}$q$::jsonb, $q$A$q$, $q$Series resistances add: 2 + 3 = 5 Ω.$q$),
  ($q$Electric Circuits$q$, $q$Two 6 Ω resistors are connected in parallel. What is equivalent resistance?$q$, $q${"A":"12 Ω","B":"3 Ω","C":"6 Ω","D":"36 Ω"}$q$::jsonb, $q$B$q$, $q$For equal parallel resistors, R_eq = R/2 = 6/2 = 3 Ω.$q$),
  ($q$Electric Circuits$q$, $q$Why are household lamps usually connected in parallel?$q$, $q${"A":"Each must carry the same current","B":"The supply voltage becomes zero","C":"Each receives supply voltage and works independently","D":"Resistance of each lamp vanishes"}$q$::jsonb, $q$C$q$, $q$Parallel branches have the same potential difference; one lamp can fail without opening others.$q$),
  ($q$Electric Circuits$q$, $q$What is the current through a 4 Ω resistor connected across 12 V?$q$, $q${"A":"48 A","B":"16 A","C":"0.33 A","D":"3 A"}$q$::jsonb, $q$D$q$, $q$I = V/R = 12/4 = 3 A.$q$),
  ($q$Electric Circuits$q$, $q$A fuse wire melts when current becomes excessive. What does this protect against?$q$, $q${"A":"Overheating and fire from fault current","B":"All power use","C":"Every voltage drop","D":"Every electromagnetic wave"}$q$::jsonb, $q$A$q$, $q$The fuse opens the circuit before excess current overheats wiring.$q$),
  ($q$Electric Circuits$q$, $q$What is the potential difference across each of two parallel branches connected to a 9 V battery?$q$, $q${"A":"4.5 V","B":"9 V","C":"18 V","D":"0 V"}$q$::jsonb, $q$B$q$, $q$Each parallel branch connects across the same two battery terminals, so each has 9 V.$q$),
  ($q$Electric Circuits$q$, $q$A 12 V source drives 2 A through a series circuit. What is its total resistance?$q$, $q${"A":"24 Ω","B":"14 Ω","C":"6 Ω","D":"0.17 Ω"}$q$::jsonb, $q$C$q$, $q$R_total = V/I = 12/2 = 6 Ω.$q$),
  ($q$Electric Circuits$q$, $q$If one component in a simple series circuit breaks, what happens to current elsewhere in that circuit?$q$, $q${"A":"It doubles","B":"It reverses","C":"It stays unchanged","D":"It stops"}$q$::jsonb, $q$D$q$, $q$A broken series path is open, so no current can flow around that loop.$q$),
  -- 15. Magnetism and induction (16)
  ($q$Magnetic Fields$q$, $q$An iron nail becomes magnetized near a strong magnet. What is this process?$q$, $q${"A":"Magnetic induction","B":"Electrolysis","C":"Refraction","D":"Fission"}$q$::jsonb, $q$A$q$, $q$A nearby field aligns domains and induces magnetism in the iron.$q$),
  ($q$Magnetic Fields$q$, $q$Two north magnetic poles are brought together. What happens?$q$, $q${"A":"They attract","B":"They repel","C":"Both disappear","D":"They become electric charges"}$q$::jsonb, $q$B$q$, $q$Like magnetic poles repel.$q$),
  ($q$Magnetic Fields$q$, $q$Why is soft iron often used as the core of an electromagnet?$q$, $q${"A":"It is a perfect insulator","B":"It never magnetizes","C":"It magnetizes strongly and demagnetizes readily","D":"It has no mass"}$q$::jsonb, $q$C$q$, $q$Soft iron strengthens the field while losing most magnetization when current stops.$q$),
  ($q$Magnetic Fields$q$, $q$What produces the magnetic field around a straight wire?$q$, $q${"A":"Only its colour","B":"Only the wire's mass","C":"Atmospheric pressure","D":"Electric current through it"}$q$::jsonb, $q$D$q$, $q$Moving charges in the wire create a surrounding magnetic field.$q$),
  ($q$Magnetic Fields$q$, $q$A compass needle aligns roughly north-south because it responds to what?$q$, $q${"A":"Earth's magnetic field","B":"Only sunlight","C":"Earth's electric current supply","D":"Air density"}$q$::jsonb, $q$A$q$, $q$The needle is a small magnet that turns with Earth's field.$q$),
  ($q$Magnetic Fields$q$, $q$How can an electromagnet's field usually be made stronger?$q$, $q${"A":"Remove all coil turns","B":"Increase current through its coil","C":"Replace iron core with air in every case","D":"Reverse the battery repeatedly at rest"}$q$::jsonb, $q$B$q$, $q$A larger current creates a stronger magnetic field, within safe limits.$q$),
  ($q$Magnetic Fields$q$, $q$What happens to a current-carrying conductor in a magnetic field if the field and current are perpendicular?$q$, $q${"A":"It necessarily becomes uncharged","B":"It becomes colder","C":"It experiences a magnetic force","D":"It stops conducting"}$q$::jsonb, $q$C$q$, $q$A magnetic field exerts a force on moving charges in the conductor.$q$),
  ($q$Magnetic Fields$q$, $q$What is the simplest way to reverse an electromagnet's north and south poles?$q$, $q${"A":"Increase its mass","B":"Remove all power","C":"Paint the core","D":"Reverse current direction"}$q$::jsonb, $q$D$q$, $q$Reversing current reverses the field direction around the coil.$q$),
  ($q$Electromagnetic Induction$q$, $q$When does a coil acquire an induced emf?$q$, $q${"A":"When magnetic flux through it changes","B":"Only when it is painted black","C":"Only when its mass increases","D":"Whenever it is stationary in a steady field"}$q$::jsonb, $q$A$q$, $q$Faraday's law links induced emf to the rate of change of magnetic flux.$q$),
  ($q$Electromagnetic Induction$q$, $q$Why does moving a magnet faster through a coil produce a larger emf?$q$, $q${"A":"The magnet gains charge","B":"The rate of flux change increases","C":"The coil loses turns","D":"Gravity is stronger"}$q$::jsonb, $q$B$q$, $q$Faster motion changes linked magnetic flux more rapidly.$q$),
  ($q$Electromagnetic Induction$q$, $q$What does Lenz's law say about induced current?$q$, $q${"A":"It always aids the change","B":"It has zero magnetic effect","C":"Its magnetic effect opposes the change producing it","D":"It flows only in vacuum"}$q$::jsonb, $q$C$q$, $q$The induced current creates a field opposing the flux change.$q$),
  ($q$Electromagnetic Induction$q$, $q$A transformer has 100 primary turns and 200 secondary turns. With 6 V AC on the primary, what is ideal secondary voltage?$q$, $q${"A":"3 V","B":"6 V","C":"12 V DC","D":"12 V AC"}$q$::jsonb, $q$D$q$, $q$V_s/V_p = N_s/N_p = 200/100 = 2, so V_s = 12 V AC.$q$),
  ($q$Electromagnetic Induction$q$, $q$Why is alternating current used in ordinary transformers?$q$, $q${"A":"Changing current provides changing magnetic flux","B":"Direct current always has infinite voltage","C":"Alternating current has no resistance","D":"It does not transfer energy"}$q$::jsonb, $q$A$q$, $q$A changing primary current creates changing core flux and hence secondary emf.$q$),
  ($q$Electromagnetic Induction$q$, $q$Why is electricity transmitted at high voltage for a given power?$q$, $q${"A":"It increases cable current","B":"It lowers current and I²R heating losses","C":"It eliminates all resistance","D":"It makes transformers unnecessary"}$q$::jsonb, $q$B$q$, $q$For fixed power P = VI, higher V means lower I, reducing resistive losses.$q$),
  ($q$Electromagnetic Induction$q$, $q$A generator converts what form of energy into electrical energy?$q$, $q${"A":"Electrical into mechanical only","B":"Heat into chemical only","C":"Mechanical into electrical","D":"Nuclear into sound directly"}$q$::jsonb, $q$C$q$, $q$Mechanical motion changes flux in a conductor, inducing electrical energy.$q$),
  ($q$Electromagnetic Induction$q$, $q$Why do eddy currents sometimes waste energy in a transformer core?$q$, $q${"A":"They remove all magnetic field","B":"They stop all induction","C":"They change iron into copper","D":"They heat the core resistively"}$q$::jsonb, $q$D$q$, $q$Circulating induced currents dissipate energy as heat in the core.$q$),
  -- 16. Atomic, nuclear and contemporary physics (16)
  ($q$Atomic and Nuclear Physics$q$, $q$Which particles make up an ordinary atomic nucleus?$q$, $q${"A":"Protons and neutrons","B":"Electrons and photons","C":"Only electrons","D":"Only neutrons"}$q$::jsonb, $q$A$q$, $q$A nucleus contains positively charged protons and neutral neutrons.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$An atom has atomic number 8 and mass number 16. How many neutrons does it have?$q$, $q${"A":"16","B":"8","C":"24","D":"0"}$q$::jsonb, $q$B$q$, $q$Neutrons = mass number − proton number = 16 − 8 = 8.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$Why do isotopes of one element have similar chemical behaviour?$q$, $q${"A":"They have identical neutron numbers","B":"They have identical mass numbers","C":"They have the same proton number and electron arrangement when neutral","D":"They have no electrons"}$q$::jsonb, $q$C$q$, $q$Chemical behaviour is largely set by electron structure, which follows proton number.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$What happens to mass number when a nucleus emits an alpha particle?$q$, $q${"A":"It increases by four","B":"It increases by two","C":"It stays fixed","D":"It decreases by four"}$q$::jsonb, $q$D$q$, $q$An alpha particle carries two protons and two neutrons, reducing mass number by four.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$A sample has half-life 10 days and starts at 80 g. How much remains after 20 days?$q$, $q${"A":"20 g","B":"40 g","C":"10 g","D":"60 g"}$q$::jsonb, $q$A$q$, $q$Two half-lives pass: 80 → 40 → 20 g.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$What distinguishes nuclear fusion from fission?$q$, $q${"A":"Fusion splits heavy nuclei","B":"Fusion joins light nuclei","C":"Fusion is only chemical burning","D":"Fusion emits no energy"}$q$::jsonb, $q$B$q$, $q$Fusion combines light nuclei; fission splits a heavy nucleus.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$Why can radiation be dangerous to living cells?$q$, $q${"A":"It always cools cells","B":"It contains no energy","C":"Ionization can damage biological molecules","D":"It stops all cell division safely"}$q$::jsonb, $q$C$q$, $q$Ionizing radiation can break or alter molecules, including DNA.$q$),
  ($q$Atomic and Nuclear Physics$q$, $q$What observation supports quantized atomic energy levels?$q$, $q${"A":"A continuous mass spectrum","B":"Identical temperature everywhere","C":"A perfectly uniform colour from every atom","D":"Atoms emit light at specific spectral lines"}$q$::jsonb, $q$D$q$, $q$Discrete photon energies arise from transitions between allowed levels.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$Why does a photoelectric surface sometimes emit no electrons even when light intensity increases?$q$, $q${"A":"Photon frequency is below threshold","B":"Light has no energy","C":"The metal has no electrons","D":"Intensity controls electron mass"}$q$::jsonb, $q$A$q$, $q$Each photon must have enough energy hf to overcome the material's work function.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$What does electron diffraction reveal?$q$, $q${"A":"Electrons are only waves with no particles","B":"Electrons can display wave behaviour","C":"Electrons have no charge","D":"All matter is light"}$q$::jsonb, $q$B$q$, $q$Diffraction is a wave phenomenon observed for electrons.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$What is the main charge carrier added by donor doping of silicon?$q$, $q${"A":"Positive protons","B":"Neutrons","C":"Free electrons","D":"Photons"}$q$::jsonb, $q$C$q$, $q$Donor impurities provide extra electrons, forming n-type material.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$Why is a diode useful in a rectifier?$q$, $q${"A":"It stores unlimited charge","B":"It produces sound","C":"It converts heat into gravity","D":"It conducts mainly in one direction"}$q$::jsonb, $q$D$q$, $q$A diode's directional conduction converts alternating flow into one-direction pulses.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$What keeps light guided inside a fibre-optic cable?$q$, $q${"A":"Total internal reflection at the core boundary","B":"Continuous creation of photons","C":"Electrical resistance alone","D":"An opaque coating that absorbs all light"}$q$::jsonb, $q$A$q$, $q$A suitably chosen core and cladding let rays reflect repeatedly within the core.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$Why must laser beams be kept away from eyes?$q$, $q${"A":"They are too slow","B":"Concentrated light can damage the retina","C":"They carry no energy","D":"They become audible in the eye"}$q$::jsonb, $q$B$q$, $q$Focused laser energy can injure sensitive eye tissue.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$A semiconductor is warmed, creating additional mobile carriers. What often happens to its conductivity?$q$, $q${"A":"It must become zero","B":"It is independent of carriers","C":"It increases","D":"It becomes negative"}$q$::jsonb, $q$C$q$, $q$Thermal energy can free more electron-hole pairs, often increasing conductivity.$q$),
  ($q$Modern Physics and Semiconductors$q$, $q$What is the main purpose of a solar photovoltaic cell?$q$, $q${"A":"To store coal","B":"To measure only sound","C":"To reflect all sunlight","D":"To convert light energy into electrical energy"}$q$::jsonb, $q$D$q$, $q$A photovoltaic junction generates electrical output when it absorbs suitable light.$q$)
)
insert into public.questions (subject_id, exam_type, source, year, topic, prompt, options, correct_answer, explanation)
select subject.id, subject.exam_type, $q$original$q$, null,
       candidate.topic, candidate.prompt, candidate.options, candidate.correct_answer, candidate.explanation
from candidates as candidate
cross join public.subjects as subject
where subject.id = '88c5efc9-7c85-440a-a6f8-902d2b81453e'::uuid
  and lower(subject.exam_type::text) = 'waec'
  and not exists (select 1 from public.questions as existing where existing.subject_id = subject.id and existing.prompt = candidate.prompt);

commit;
